-- ============================================================
-- RateBench — Galerie multi-photos + au moins un avis par banc
-- Complète la migration 006 (55 bancs réels). Idempotent.
-- ============================================================

create table if not exists public.bench_photos (
  id uuid primary key default gen_random_uuid(),
  bench_id uuid not null references public.benches(id) on delete cascade,
  photo_url text not null,
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);
create index if not exists bench_photos_bench_idx on public.bench_photos (bench_id, sort_order);
alter table public.bench_photos enable row level security;
drop policy if exists "Lecture publique des photos de bancs" on public.bench_photos;
create policy "Lecture publique des photos de bancs"
  on public.bench_photos for select using (true);

-- 3 photos par banc (URLs Wikimedia Commons, déjà utilisées en démo)
select b.id, p.url, p.ord
from public.benches b
cross join lateral (values
  ('https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/A_bench_in_Lewes_Castle_Gun_Garden.jpg/960px-A_bench_in_Lewes_Castle_Gun_Garden.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 0),
  ('https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/A_lawn_and_garden_bench_at_Gibberd_Garden_Essex_England.JPG/960px-A_lawn_and_garden_bench_at_Gibberd_Garden_Essex_England.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 1),
  ('https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Beer_garden_bench_The_Cock_Inn_Henham_Essex_England_01.jpg/960px-Beer_garden_bench_The_Cock_Inn_Henham_Essex_England_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 2)
) as p(url, ord)
where b.id like '00000000-0000-4000-8000-%'
on conflict do nothing;

-- Au moins un avis par banc (contenu de démonstration)
on conflict (id) do nothing;
